class OuterComputer {
    private String model = "SuperCompute 9000";
    private static String osVersion = "Enterprise Linux 10";

    // 1. Static Nested Class: Independent of OuterComputer instance
    public static class HardwareSpecs {
        private int ramGb;
        public HardwareSpecs(int ram) { this.ramGb = ram; }
        public void printSpecs() {
            // Can access static members of outer class:
            System.out.println("OS: " + osVersion + " | RAM: " + ramGb + " GB");
            // System.out.println(model); // COMPILE ERROR: Cannot access non-static model!
        }
    }

    // 2. Non-Static Inner Class: Bound to specific OuterComputer instance
    public class DiagnosticTool {
        public void inspect() {
            // Seamless access to outer private instance fields via OuterComputer.this
            System.out.println("Diagnostics running on " + model);
        }
    }
}

public class NestedClassesDemo {
    public static void main(String[] args) {
        // Instantiating static nested class: NO outer instance needed!
        OuterComputer.HardwareSpecs specs = new OuterComputer.HardwareSpecs(64);
        specs.printSpecs();

        // Instantiating non-static inner class: REQUIRES outer instance!
        OuterComputer pc = new OuterComputer();
        OuterComputer.DiagnosticTool diag = pc.new DiagnosticTool();
        diag.inspect();
    }
}

