public final class UserAccount {
    private final String username;
    private final String email;
    private final boolean premium;

    // Private constructor: only Builder can instantiate
    private UserAccount(Builder builder) {
        this.username = builder.username;
        this.email = builder.email;
        this.premium = builder.premium;
    }

    public String getUsername() { return username; }
    public String getEmail() { return email; }
    public boolean isPremium() { return premium; }

    // Static nested Builder
    public static class Builder {
        private String username;
        private String email;
        private boolean premium = false;

        public Builder setUsername(String username) {
            this.username = username;
            return this;
        }
        public Builder setEmail(String email) {
            this.email = email;
            return this;
        }
        public Builder setPremium(boolean premium) {
            this.premium = premium;
            return this;
        }
        public UserAccount build() {
            if (username == null || email == null) {
                throw new IllegalStateException("Username and email required");
            }
            return new UserAccount(this);
        }
    }
}

public class BuilderDemo {
    public static void main(String[] args) {
        UserAccount user = new UserAccount.Builder()
            .setUsername("munaf085")
            .setEmail("munaf@example.com")
            .setPremium(true)
            .build();

        System.out.println("Created: " + user.getUsername() + " (" + user.getEmail() + ") Premium: " + user.isPremium());
    }
}

