public class Geometry {
    public static class Point2D {
        public int x, y;
        public Point2D(int x, int y) {
            this.x = x;
            this.y = y;
        }
        public double distanceFromOrigin() {
            return Math.sqrt(x * x + y * y);
        }
    }

    public static void main(String[] args) {
        Geometry.Point2D p = new Geometry.Point2D(3, 4);
        System.out.println("Distance: " + p.distanceFromOrigin());
    }
}

class BankAccount {
    private String owner;
    private double[] transactions;

    public BankAccount(String owner, double[] transactions) {
        this.owner = owner;
        this.transactions = (transactions != null) ? transactions.clone() : new double[0];
    }

    public class TransactionPrinter {
        public void printAll() {
            for (double tx : transactions) {
                System.out.println(owner + " Transaction: $" + tx);
            }
        }
    }

    public TransactionPrinter getPrinter() {
        return new TransactionPrinter();
    }
}

public class InnerBankApp {
    public static void main(String[] args) {
        BankAccount acc = new BankAccount("Alice", new double[]{100.0, -25.0, 50.0});
        BankAccount.TransactionPrinter printer = acc.getPrinter();
        printer.printAll();
    }
}

final class Pizza {
    private final String size;
    private final boolean cheese;
    private final boolean pepperoni;
    private final boolean mushrooms;

    private Pizza(Builder b) {
        this.size = b.size;
        this.cheese = b.cheese;
        this.pepperoni = b.pepperoni;
        this.mushrooms = b.mushrooms;
    }

    public String getSize() { return size; }
    public boolean hasCheese() { return cheese; }
    public boolean hasPepperoni() { return pepperoni; }
    public boolean hasMushrooms() { return mushrooms; }

    public void describe() {
        System.out.println(size + " pizza: cheese=" + cheese + ", pepperoni=" + pepperoni + ", mushrooms=" + mushrooms);
    }

    public static class Builder {
        private String size;
        private boolean cheese = false;
        private boolean pepperoni = false;
        private boolean mushrooms = false;

        public Builder(String size) { this.size = size; }
        public Builder addCheese() { this.cheese = true; return this; }
        public Builder addPepperoni() { this.pepperoni = true; return this; }
        public Builder addMushrooms() { this.mushrooms = true; return this; }
        public Pizza build() { return new Pizza(this); }
    }
}

public class PizzaApp {
    public static void main(String[] args) {
        Pizza p = new Pizza.Builder("Large")
            .addCheese()
            .addPepperoni()
            .build();
        p.describe();
    }
}

