class CoordinateSpace {
    int x = 10;
    int y = 20;

    class Transform {
        int x = 5;
        int y = 5;

        public void printCombinedCoordinates() {
            System.out.println("Local: (" + this.x + ", " + this.y + ")");
            System.out.println("Outer: (" + CoordinateSpace.this.x + ", " + CoordinateSpace.this.y + ")");
            System.out.println("Sum: (" + (this.x + CoordinateSpace.this.x) + ", " + (this.y + CoordinateSpace.this.y) + ")");
        }
    }
}

public class DisambiguateApp {
    public static void main(String[] args) {
        CoordinateSpace space = new CoordinateSpace();
        CoordinateSpace.Transform t = space.new Transform();
        t.printCombinedCoordinates();
    }
}
